<?php

namespace App\Services\Sales;
use App\Models\Business;use App\Models\Order;use App\Models\OrderItem;use App\Models\User;use App\Models\VenueTable;use Brick\Math\BigDecimal;use Brick\Math\RoundingMode;use Carbon\CarbonImmutable;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
final class OrderTransferService{
 private const EDITABLE=['open','payment_due'];public function __construct(private readonly OrderTotalsCalculator $totals){}
 public function split(Business$b,User$u,Order$s,array$p):array{return DB::transaction(function()use($b,$u,$s,$p){$s=$this->lockOrder($b,(string)$s->getKey());if($r=$this->replay($b,$p['idempotency_key'],'split',(string)$s->getKey(),null,$p))return$r;$this->assertTransferable($s);$this->assertNoDiscount($s);$items=OrderItem::query()->forBusiness($b)->where('order_id',$s->getKey())->whereIn('id',$p['item_ids'])->orderBy('id')->lockForUpdate()->get();if($items->count()!==count($p['item_ids']))throw ValidationException::withMessages(['item_ids'=>'One or more selected items do not belong to this order.']);if($items->contains(fn(OrderItem$i)=>$i->preparation_status==='voided'))throw ValidationException::withMessages(['item_ids'=>'Voided items cannot be split.']);$active=OrderItem::query()->forBusiness($b)->where('order_id',$s->getKey())->where('preparation_status','!=','voided')->orderBy('id')->lockForUpdate()->get();if($items->count()>=$active->count())throw ValidationException::withMessages(['item_ids'=>'A split must leave at least one active item on the source order.']);$tid=$p['venue_table_id']??null;if($tid!==null){if($s->type!=='table')throw ValidationException::withMessages(['venue_table_id'=>'Only table orders can be split to another table.']);$this->lockAvailableTable($b,$s,$tid);}$before=BigDecimal::of((string)$s->grand_total);$d=Order::create(['business_id'=>$b->getKey(),'location_id'=>$s->location_id,'venue_table_id'=>$tid??$s->venue_table_id,'opened_by_user_id'=>$u->getKey(),'number'=>$this->nextNumber($b),'type'=>$s->type,'status'=>'open','currency'=>$s->currency,'subtotal'=>'0.0000','discount_total'=>'0.0000','tax_total'=>'0.0000','grand_total'=>'0.0000','opened_at'=>now()]);OrderItem::whereIn('id',$items->pluck('id'))->update(['order_id'=>$d->getKey(),'updated_at'=>now()]);$s=$this->recalculate($s);$d=$this->recalculate($d);$this->assertConserved($before,$s,$d);$this->audit($b,$u,'split',$p['idempotency_key'],$s,$d,$items->pluck('id')->all(),$p['reason'],$before,$p);return['source'=>$s,'destination'=>$d];},attempts:3);}
 public function merge(Business$b,User$u,Order$d,array$p):Order{return DB::transaction(function()use($b,$u,$d,$p){$sid=(string)$p['source_order_id'];$did=(string)$d->getKey();if($did===$sid)throw ValidationException::withMessages(['source_order_id'=>'An order cannot be merged into itself.']);$ids=collect([$did,$sid])->sort()->values();$locked=Order::query()->forBusiness($b)->whereIn('id',$ids)->orderBy('id')->lockForUpdate()->get()->keyBy(fn(Order$o)=>(string)$o->getKey());if($locked->count()!==2)abort(404);$d=$locked->get($did);$s=$locked->get($sid);if(!$d||!$s)abort(404);if($r=$this->replay($b,$p['idempotency_key'],'merge',$sid,$did,$p))return$r['destination'];$this->assertTransferable($s);$this->assertTransferable($d);$this->assertNoDiscount($s);$this->assertNoDiscount($d);if((string)$s->location_id!==(string)$d->location_id)throw ValidationException::withMessages(['source_order_id'=>'Orders from different locations cannot be merged.']);if((string)$s->currency!==(string)$d->currency)throw ValidationException::withMessages(['source_order_id'=>'Orders with different currencies cannot be merged.']);$orderIds=collect([$sid,$did])->sort()->values();$li=OrderItem::query()->forBusiness($b)->whereIn('order_id',$orderIds)->orderBy('order_id')->orderBy('id')->lockForUpdate()->get();$si=$li->filter(fn(OrderItem$i)=>(string)$i->order_id===$sid&&$i->preparation_status!=='voided');if($si->isEmpty())throw ValidationException::withMessages(['source_order_id'=>'Source order has no active items to merge.']);$before=BigDecimal::of((string)$s->grand_total)->plus((string)$d->grand_total);OrderItem::whereIn('id',$si->pluck('id'))->update(['order_id'=>$d->getKey(),'updated_at'=>now()]);$d=$this->recalculate($d);$s->forceFill(['status'=>'closed','closed_at'=>now(),'subtotal'=>'0.0000','tax_total'=>'0.0000','grand_total'=>'0.0000'])->save();$s=$s->fresh(['items','payments.refunds']);$this->assertConserved($before,$s,$d);$this->audit($b,$u,'merge',$p['idempotency_key'],$s,$d,$si->pluck('id')->all(),$p['reason'],$before,$p);return$d;},attempts:3);}
 private function replay(Business$b,string$key,string$op,string$sid,?string$did,array$p):?array{$a=DB::table('order_transfer_audits')->where('business_id',$b->getKey())->where('idempotency_key',$key)->lockForUpdate()->first();if(!$a)return null;$same=$a->operation===$op&&(string)$a->source_order_id===$sid&&($did===null||(string)$a->destination_order_id===$did)&&$this->samePayload($a,$p);if(!$same)throw ValidationException::withMessages(['idempotency_key'=>'This idempotency key was already used for a different order transfer request.']);$s=Order::query()->forBusiness($b)->whereKey($a->source_order_id)->firstOrFail();$d=Order::query()->forBusiness($b)->whereKey($a->destination_order_id)->firstOrFail();return['source'=>$s->load('items'),'destination'=>$d->load('items')];}
 private function samePayload(object$a,array$p):bool{$stored=json_decode($a->request_snapshot??'{}',true);return is_array($stored)&&$this->canonicalize($stored)===$this->canonicalize($this->transferSnapshot($p));}private function transferSnapshot(array$p):array{return['item_ids'=>array_values($p['item_ids']??[]),'venue_table_id'=>$p['venue_table_id']??null,'source_order_id'=>$p['source_order_id']??null,'reason'=>trim((string)($p['reason']??''))];}private function canonicalize(array$v):array{foreach($v as$k=>$i)if(is_array($i))$v[$k]=$this->canonicalize($i);if(array_is_list($v)){sort($v,SORT_STRING);return$v;}ksort($v,SORT_STRING);return$v;}
 private function lockOrder(Business$b,string$id):Order{return Order::query()->forBusiness($b)->whereKey($id)->lockForUpdate()->firstOrFail();}private function assertTransferable(Order$o):void{if(!in_array($o->status,self::EDITABLE,true))throw ValidationException::withMessages(['order'=>'This order cannot be split or merged in its current state.']);if($o->payments()->whereNotIn('status',['failed','cancelled','voided'])->exists())throw ValidationException::withMessages(['order'=>'Split and merge are blocked after payment has started.']);}private function assertNoDiscount(Order$o):void{if(BigDecimal::of((string)$o->discount_total)->isPositive())throw ValidationException::withMessages(['order'=>'Remove the order-level discount before split or merge so financial allocation remains explicit.']);}
 private function lockAvailableTable(Business$b,Order$s,string$id):void{VenueTable::query()->forBusiness($b)->whereKey($id)->where('location_id',$s->location_id)->where('is_active',true)->lockForUpdate()->firstOrFail();$occupied=Order::query()->forBusiness($b)->where('location_id',$s->location_id)->where('venue_table_id',$id)->whereIn('status',self::EDITABLE)->where($s->getKeyName(),'!=',$s->getKey())->lockForUpdate()->first();if($occupied)throw ValidationException::withMessages(['venue_table_id'=>'Destination table already has an active order; merge into that order instead.']);}
 private function recalculate(Order$o):Order{$items=OrderItem::query()->forBusiness($o->business_id)->where('order_id',$o->getKey())->where('preparation_status','!=','voided')->get();if($items->isEmpty()){$o->forceFill(['subtotal'=>'0.0000','tax_total'=>'0.0000','grand_total'=>'0.0000'])->save();return$o->fresh(['items','payments.refunds']);}$c=$this->totals->calculate($items->map(fn(OrderItem$i)=>['quantity'=>(string)$i->quantity,'unit_price'=>(string)$i->unit_price,'tax_rate'=>(string)$i->tax_rate])->all());$o->forceFill(['subtotal'=>$c['subtotal'],'tax_total'=>$c['tax_total'],'grand_total'=>$c['grand_total']])->save();return$o->fresh(['items','payments.refunds']);}private function assertConserved(BigDecimal$b,Order$s,Order$d):void{if(!$b->isEqualTo(BigDecimal::of((string)$s->grand_total)->plus((string)$d->grand_total)))throw ValidationException::withMessages(['order'=>'Financial conservation check failed; no split or merge was committed.']);}
 private function audit(Business$b,User$u,string$op,string$key,Order$s,Order$d,array$ids,string$reason,BigDecimal$before,array$p):void{DB::table('order_transfer_audits')->insert(['id'=>(string)Str::ulid(),'business_id'=>$b->getKey(),'location_id'=>$s->location_id,'source_order_id'=>$s->getKey(),'destination_order_id'=>$d->getKey(),'performed_by_user_id'=>$u->getKey(),'operation'=>$op,'idempotency_key'=>$key,'reason'=>trim($reason),'total_before'=>(string)$before->toScale(4,RoundingMode::HALF_UP),'source_total_after'=>(string)BigDecimal::of((string)$s->grand_total)->toScale(4,RoundingMode::HALF_UP),'destination_total_after'=>(string)BigDecimal::of((string)$d->grand_total)->toScale(4,RoundingMode::HALF_UP),'item_ids'=>json_encode(array_values($ids),JSON_THROW_ON_ERROR),'request_snapshot'=>json_encode($this->transferSnapshot($p),JSON_THROW_ON_ERROR),'performed_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);}private function nextNumber(Business$b):string{$n=CarbonImmutable::now($b->timezone);$date=$n->toDateString();DB::statement('INSERT INTO business_order_counters (business_id,business_date,last_number,created_at,updated_at) VALUES (?,?,LAST_INSERT_ID(1),UTC_TIMESTAMP(),UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE last_number=LAST_INSERT_ID(last_number+1),updated_at=UTC_TIMESTAMP()',[$b->getKey(),$date]);$seq=(int)DB::selectOne('SELECT LAST_INSERT_ID() AS sequence')->sequence;return sprintf('%s-%04d',$n->format('Ymd'),$seq);}
}
